@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Rajdhani:wght@500;600;700&display=swap');
:root{color-scheme:dark;--bg:#10191f;--panel:#172229;--panel2:#1d2b32;--line:#34464d;--muted:#849398;--text:#e5ece8;--blue:#43c9dc;--orange:#f0a849;--red:#e46d5c;--mono:'DM Mono',monospace;--display:'Barlow Condensed',Impact,sans-serif;--body:'Rajdhani',sans-serif}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--text);font-family:var(--body);user-select:none;-webkit-user-select:none;touch-action:manipulation}.game-shell{height:100dvh;min-height:480px;display:flex;flex-direction:column;background:radial-gradient(ellipse at 42% 42%,#1a2a30 0,#10191f 67%)}.topbar{height:72px;flex:none;display:flex;align-items:center;padding:0 24px;border-bottom:1px solid #29383d;background:#131e24;gap:22px;z-index:2}.brand{display:flex;align-items:center;gap:11px;min-width:236px}.brand-mark{width:37px;height:37px;display:grid;place-items:center;background:var(--blue);color:#112126;clip-path:polygon(0 0,100% 0,100% 72%,72% 100%,0 100%);font:900 19px var(--display);letter-spacing:-1px}.brand strong{display:block;font:800 21px/.9 var(--display);letter-spacing:1.6px;color:#f1f3ea}.brand small{display:block;margin-top:5px;font:9px var(--mono);letter-spacing:1.15px;color:#86969a}.status-pills{display:flex;gap:8px;align-items:center}.stat{height:43px;min-width:116px;padding:4px 11px;display:grid;grid-template-columns:18px auto;grid-template-rows:20px 11px;align-items:center;border:1px solid #2e4046;background:#18262c}.stat>span:nth-child(2){font:600 16px var(--mono);color:#e4ece8}.stat small{grid-column:2;font:8px var(--mono);letter-spacing:1px;color:#84949a;line-height:8px}.stat-icon{grid-row:1/3;font-size:15px}.credits{color:var(--orange)}.power{color:var(--blue)}.stat.threat{min-width:auto;height:31px;display:flex;gap:7px;padding:0 11px;border-color:#35443f;background:#1a2926;font:10px var(--mono);letter-spacing:.7px;color:#a6c2ab}.threat i,.live-dot{width:6px;height:6px;border-radius:50%;background:#79d289;box-shadow:0 0 9px #79d289}.icon-button{margin-left:auto;width:36px;height:36px;border:1px solid #35464c;background:#19262c;color:#a8b6b5;font-size:18px;cursor:pointer}.icon-button.muted{color:#58676c}.layout{flex:1;min-height:0;display:grid;grid-template-columns:minmax(0,1fr) 332px;gap:14px;padding:14px 18px 10px}.battlefield-wrap{min-width:0;min-height:0;display:flex;flex-direction:column;border:1px solid #33454a;background:#132026;box-shadow:0 12px 35px #06101370}.battlefield-top{height:49px;flex:none;padding:0 16px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #314247;background:#19272d}.mission{display:flex;align-items:center;gap:10px}.mission .live-dot{width:7px;height:7px}.mission b,.objective b{display:block;font:700 13px var(--display);letter-spacing:1.05px;color:#d9e3dd}.mission small,.objective small{display:block;color:#809096;font:10px var(--mono);margin-top:1px}.clock{padding:5px 9px;border:1px solid #36484d;background:#142126;color:#b9c9c4;font:12px var(--mono)}.clock span{color:#8aa2a1;margin-right:6px}.canvas-frame{flex:1;min-height:0;position:relative;overflow:hidden;background:#293b3a}.canvas-frame:after{content:"";position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 90px #09141370,inset 0 0 0 1px #ffffff08}.canvas-frame canvas{display:block;width:100%;height:100%;touch-action:none;cursor:crosshair}.map-label{position:absolute;z-index:1;pointer-events:none;color:#b8d2c75e;font:9px var(--mono);letter-spacing:1.8px}.label-nw{top:14px;left:15px}.label-se{bottom:13px;right:15px;color:#e3a58a55}.toast{position:absolute;left:50%;top:13px;transform:translate(-50%,-12px);padding:8px 13px;border:1px solid #546459;background:#182822e8;color:#cee4d2;font:11px var(--mono);letter-spacing:.2px;opacity:0;transition:.2s;pointer-events:none;white-space:nowrap;z-index:2}.toast.show{opacity:1;transform:translate(-50%,0)}.battlefield-footer{height:51px;flex:none;display:flex;align-items:center;justify-content:space-between;padding:0 15px;background:#17242a;border-top:1px solid #314247}.objective{display:flex;align-items:center;gap:10px}.objective-icon{font-size:21px;color:var(--orange)}.objective b{font-size:11px}.objective small{font-size:9px}.mini-legend{display:flex;gap:14px;font:9px var(--mono);color:#8b9b9c}.mini-legend span{display:flex;align-items:center;gap:5px}.mini-legend i{width:7px;height:7px;display:inline-block;border-radius:50%}.legend-blue{background:var(--blue)}.legend-red{background:var(--red)}
.command-panel{min-height:0;display:flex;flex-direction:column;padding:15px 15px 12px;background:#172329;border:1px solid #34464b;box-shadow:0 12px 35px #06101350}.panel-heading{display:flex;align-items:center;justify-content:space-between;padding:1px 1px 12px;border-bottom:1px solid #304147}.panel-heading small{font:9px var(--mono);letter-spacing:1.3px;color:#7f9296}.panel-heading h2{margin:0;font:800 25px/.95 var(--display);letter-spacing:1px}.signal{font:9px var(--mono);color:#78c6a4}.selection-card{height:92px;flex:none;display:flex;align-items:center;gap:11px;padding:10px 0;border-bottom:1px solid #304147}.selection-art{width:58px;height:60px;flex:none;display:grid;place-items:center;background:linear-gradient(145deg,#293b3f,#1b2b30);border:1px solid #3c5156;color:#60c8d0;font-size:26px}.selection-info{min-width:0;flex:1}.selection-info>small{display:block;color:#8aa0a1;font:9px var(--mono);letter-spacing:.8px}.selection-info>b{display:block;margin-top:2px;font:700 16px var(--display);letter-spacing:.4px}.health-track{height:4px;margin:6px 0 4px;background:#354448}.health-track i{height:100%;width:100%;display:block;background:linear-gradient(90deg,#56c98f,#95d891);transition:width .2s}.selection-meta{font:9px var(--mono);color:#829496;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.section-title{display:flex;justify-content:space-between;align-items:center;padding:13px 0 9px;color:#90a2a3;font:9px var(--mono);letter-spacing:.8px}.section-title i{font-style:normal;color:#829398}.action-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px}.action-card{height:58px;min-width:0;position:relative;display:flex;align-items:center;gap:8px;padding:7px;border:1px solid #34474c;background:#1c2a30;color:var(--text);text-align:left;cursor:pointer;transition:background .12s,border .12s,transform .12s}.action-card:hover{background:#263a40;border-color:#4b777b;transform:translateY(-1px)}.action-card:active{transform:translateY(1px)}.action-card.disabled{opacity:.42;filter:grayscale(.45)}.action-symbol{width:28px;height:28px;flex:none;display:grid;place-items:center;background:#25383d;color:#64cbd5;font-size:19px}.action-card:nth-child(2) .action-symbol{color:#e0a85e}.action-card:nth-child(3) .action-symbol,.action-card:nth-child(4) .action-symbol{color:#91c892}.action-card:nth-child(5) .action-symbol{color:#eac065}.action-label{min-width:0}.action-label b{display:block;white-space:nowrap;font:700 11px var(--display);letter-spacing:.45px}.action-label small{display:block;margin-top:3px;white-space:nowrap;color:#8c9da0;font:8px var(--mono)}.action-key{position:absolute;right:5px;top:3px;color:#75888d;font:8px var(--mono)}.command-action{grid-column:1/-1;height:45px}.command-action .action-symbol{width:27px;height:26px;color:#e0b768}.panel-bottom{margin-top:auto;min-height:45px;display:flex;align-items:center;gap:9px;border-top:1px solid #304147;padding-top:8px}.tip-icon{width:17px;height:17px;flex:none;display:grid;place-items:center;border:1px solid #648083;border-radius:50%;color:#85b4b1;font:11px Georgia}.panel-bottom p{margin:0;color:#829398;font:10px/1.35 var(--mono)}.bottomline{height:26px;flex:none;display:flex;align-items:center;justify-content:space-between;padding:0 22px;color:#65777b;font:8px var(--mono);letter-spacing:.5px}.bottomline b{color:#91a09c;font-weight:400}.bottomline i{font-style:normal;color:#3e5155;margin:0 4px}.result-overlay{position:fixed;inset:0;z-index:5;display:none;place-items:center;background:#081114ce;backdrop-filter:blur(4px)}.result-overlay.show{display:grid}.result-card{width:min(390px,calc(100vw - 32px));padding:32px;text-align:center;border:1px solid #607268;background:linear-gradient(145deg,#20332f,#142229);box-shadow:0 20px 90px #000b}.result-mark{width:55px;height:55px;margin:0 auto 15px;display:grid;place-items:center;border:1px solid #79bd8b;color:#8fdaa0;font-size:28px}.result-card>small{font:10px var(--mono);letter-spacing:2px;color:#89c699}.result-card h1{margin:8px 0;font:900 35px/.95 var(--display);letter-spacing:1.5px}.result-card p{color:#a7b5af;font:14px var(--body)}.result-card button{margin-top:14px;padding:12px 20px;border:0;background:#59c9d4;color:#112126;font:800 14px var(--display);letter-spacing:1px;cursor:pointer}.result-card button span{margin-left:10px;font-size:18px}
@media(max-width:850px){.topbar{height:60px;padding:0 12px;gap:10px}.brand{min-width:0;flex:1}.brand-mark{width:32px;height:32px;font-size:17px}.brand strong{font-size:18px}.brand small{font-size:7px}.status-pills{gap:4px}.stat{height:38px;min-width:78px;padding:4px 6px;grid-template-columns:14px auto}.stat>span:nth-child(2){font-size:12px}.stat small{font-size:7px}.stat.threat{min-width:0;padding:0 7px;font-size:0}.stat.threat i{margin:0}.icon-button{width:32px;height:32px}.layout{padding:8px;gap:8px;grid-template-columns:minmax(0,1fr) 268px}.command-panel{padding:10px}.panel-heading h2{font-size:22px}.action-grid{gap:5px}.action-card{height:53px;padding:5px;gap:6px}.action-symbol{width:24px;height:25px;font-size:16px}.action-label b{font-size:10px}.action-label small{font-size:7px}.bottomline{padding:0 10px;font-size:7px}}
@media(max-width:620px){.game-shell{min-height:0}.topbar{height:55px;padding:0 9px;gap:6px}.brand{gap:7px}.brand-mark{width:29px;height:29px;font-size:15px}.brand strong{font-size:16px;letter-spacing:1px}.brand small{margin-top:3px;font-size:6px;letter-spacing:.7px}.status-pills{gap:3px}.stat{min-width:63px;height:34px;padding:3px 4px;grid-template-columns:12px auto;grid-template-rows:16px 9px}.stat>span:nth-child(2){font-size:10px}.stat small{font-size:6px;letter-spacing:.4px}.stat-icon{font-size:12px}.stat.threat{display:none}.icon-button{width:28px;height:28px;font-size:15px}.layout{padding:6px;gap:6px;display:flex;flex-direction:column}.battlefield-wrap{flex:1;min-height:0}.battlefield-top{height:39px;padding:0 10px}.mission{gap:7px}.mission b{font-size:11px}.mission small{font-size:8px}.clock{font-size:10px;padding:4px 6px}.battlefield-footer{height:37px;padding:0 9px}.objective{gap:6px}.objective-icon{font-size:17px}.objective b{font-size:9px}.objective small{font-size:7px}.mini-legend{gap:8px;font-size:7px}.canvas-frame{min-height:80px}.command-panel{flex:none;padding:7px 8px 5px;display:grid;grid-template-columns:minmax(135px,.75fr) minmax(0,1.4fr);grid-template-rows:auto 1fr;column-gap:9px;row-gap:0}.panel-heading{grid-column:1;border:0;padding:0 0 4px}.panel-heading small{font-size:7px}.panel-heading h2{font-size:19px}.signal{font-size:7px}.selection-card{grid-column:1;grid-row:2;height:auto;min-height:59px;border:0;padding:2px 0}.selection-art{width:39px;height:43px;font-size:18px}.selection-info>small{font-size:7px}.selection-info>b{font-size:13px}.health-track{margin:4px 0 3px}.selection-meta{font-size:7px}.section-title{grid-column:2;grid-row:1;padding:2px 0 5px;font-size:7px}.action-grid{grid-column:2;grid-row:2;grid-template-columns:1fr 1fr;grid-template-rows:repeat(3,34px);gap:3px;align-content:start}.action-card{height:34px;gap:4px;padding:3px}.action-symbol{width:20px;height:23px;font-size:14px}.action-label b{font-size:8px;letter-spacing:0}.action-label small{font-size:6px;margin-top:1px}.action-key{display:none}.command-action{grid-column:auto;height:34px}.command-action .action-symbol{width:20px;height:23px}.panel-bottom{display:none}.bottomline{height:18px;padding:0 8px;font-size:6px}.bottomline span:last-child{display:none}}
@media(max-height:650px) and (min-width:621px){.topbar{height:56px}.layout{padding-top:8px;padding-bottom:5px}.command-panel{padding:9px 12px}.selection-card{height:74px}.action-card{height:49px}.command-action{height:39px}.battlefield-top{height:40px}.battlefield-footer{height:42px}.bottomline{height:20px}}

(() => {
  'use strict';
  const canvas = document.getElementById('battlefield');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const COLS = 22, ROWS = 16;
  const state = { credits:1200, power:80, powerMax:100, elapsed:0, units:[], buildings:[], effects:[], selected:[], mode:null, rally:{x:6.5,y:8}, gameOver:false, muted:false, lastTime:0, toastTimer:0, spawnTimer:27, aiTimer:18, kills:0 };
  let W=1,H=1,DPR=1,tw=30,th=15, originX=0,originY=0, pointer=null;
  const terrainSeed = (x,y) => {const n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)};
  const makeUnit=(team,type,x,y)=>{const tank=type==='tank';return {id:Math.random(),team,type,x,y,hp:tank?170:85,maxHp:tank?170:85,speed:tank?1.05:1.55,range:tank?3.5:2.55,damage:tank?27:12,rate:tank?1.05:.82,cooldown:Math.random()*.4,target:null,move:null,dir:0,flash:0}};
  const makeBuilding=(team,type,x,y)=>{const data={hq:[760,760,0,0],barracks:[350,390,0,0],refinery:[500,300,0,0],generator:[350,280,0,0],turret:[450,270,3.8,24] }[type];return {id:Math.random(),team,type,x,y,hp:data[0],maxHp:data[0],size:type==='hq'?1.5:type==='refinery'?1.15:.92,range:data[2],damage:data[3],cooldown:0}};
  state.buildings.push(makeBuilding('blue','hq',3.3,7.8),makeBuilding('blue','barracks',5.3,5.1),makeBuilding('blue','generator',4.6,10.3),makeBuilding('red','hq',18.7,7.8),makeBuilding('red','barracks',17.2,5.2),makeBuilding('red','generator',18,10.2));
  state.units.push(makeUnit('blue','infantry',6.6,7.1),makeUnit('blue','infantry',7.4,8.05),makeUnit('blue','infantry',6.2,8.9),makeUnit('red','infantry',16.1,7.2),makeUnit('red','infantry',15.7,8.2));
  const dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function resize(){const r=canvas.getBoundingClientRect();DPR=Math.min(window.devicePixelRatio||1,2);W=Math.max(1,r.width);H=Math.max(1,r.height);canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0);const fit=Math.min(W/(COLS+ROWS)*1.78,H/(COLS+ROWS)*1.67);tw=fit;th=fit*.52;originX=W/2-(COLS-ROWS)*tw/4;originY=H/2-(COLS+ROWS)*th/4;}
  new ResizeObserver(resize).observe(canvas); resize();
  function project(x,y){return {x:originX+(x-y)*tw/2,y:originY+(x+y)*th/2};}
  function unproject(sx,sy){const dx=(sx-W/2)*2/tw,dy=(sy-H/2)*2/th;return {x:(dx+dy+COLS)/2,y:(dy-dx+ROWS)/2};}
  function toast(message){const el=$('toast');el.textContent=message;el.classList.add('show');state.toastTimer=2.2;}
  function ui(){ $('credits').textContent=Math.floor(state.credits).toLocaleString();$('power').textContent=`${state.power} / ${state.powerMax}`;$('clock').textContent=`${String(Math.floor(state.elapsed/60)).padStart(2,'0')}:${String(Math.floor(state.elapsed%60)).padStart(2,'0')}`;const alive=state.units.filter(u=>u.team==='blue').length;$('unitCount').textContent=`FORCES: ${alive} ${alive===1?'UNIT':'UNITS'}`;const picked=state.selected.map(id=>findEntity(id)).filter(Boolean);if(picked.length===1){const e=picked[0],isUnit='team'in e&&!('size'in e);$('selectionType').textContent=e.team==='blue'?'ALLIED '+(isUnit?'UNIT':'STRUCTURE'):'HOSTILE '+(isUnit?'UNIT':'STRUCTURE');$('selectionName').textContent=(e.type==='hq'?'COMMAND CORE':e.type==='infantry'?'RIFLE SQUAD':e.type==='tank'?'STRIKE TANK':e.type.toUpperCase());$('selectionHealth').style.width=`${Math.max(0,e.hp/e.maxHp*100)}%`;$('selectionMeta').textContent=`${Math.ceil(e.hp)} / ${e.maxHp} HP${isUnit?` · ${e.type==='tank'?'ARMORED':'MOBILE'}`:''}`;$('selectionArt').innerHTML=`<span>${e.type==='hq'?'⌂':e.type==='infantry'?'♟':e.type==='tank'?'▰':e.type==='turret'?'⌖':'▤'}</span>`;}else if(picked.length>1){$('selectionType').textContent='BATTLE GROUP';$('selectionName').textContent=`${picked.length} UNITS SELECTED`;$('selectionHealth').style.width='100%';$('selectionMeta').textContent='Move · attack · regroup';$('selectionArt').innerHTML='<span>♟</span>';}else{$('selectionType').textContent='FIELD OVERVIEW';$('selectionName').textContent=state.mode?state.mode==='rally'?'SET RALLY POINT':'PLACE '+state.mode.toUpperCase():'Awaiting orders';$('selectionHealth').style.width='100%';$('selectionMeta').textContent='Select a unit or structure';$('selectionArt').innerHTML='<span>⌖</span>';}}
  function findEntity(id){return state.units.find(x=>x.id===id)||state.buildings.find(x=>x.id===id)}
  function ownerHas(type){return state.buildings.some(b=>b.team==='blue'&&b.type===type)}
  function canBuild(action){if(state.gameOver)return false;if(action==='infantry'||action==='tank')return ownerHas('barracks');if(action==='rally')return true;return true;}
  function syncButtons(){document.querySelectorAll('.action-card').forEach(b=>b.classList.toggle('disabled',!canBuild(b.dataset.action)||(b.dataset.action==='tank'&&state.credits<600)));}
  function drawDiamond(x,y,fill,stroke){const p=project(x,y);ctx.beginPath();ctx.moveTo(p.x,p.y-th/2);ctx.lineTo(p.x+tw/2,p.y);ctx.lineTo(p.x,p.y+th/2);ctx.lineTo(p.x-tw/2,p.y);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.55;ctx.stroke();}}
  function drawGround(){
    const grad=ctx.createLinearGradient(0,0,W,H);grad.addColorStop(0,'#506052');grad.addColorStop(.5,'#394b43');grad.addColorStop(1,'#353f3c');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);
    for(let d=0;d<COLS+ROWS;d++)for(let x=Math.max(0,d-ROWS+1);x<COLS&&x<=d;x++){const y=d-x;if(y<0||y>=ROWS)continue;const n=terrainSeed(x,y);let c=n>.86?'#52604d':n>.68?'#455547':n>.42?'#405047':'#3d4c43';if((x===10||x===11)&&y>2&&y<14)c=n>.7?'#554e3e':'#504b3d';drawDiamond(x+.5,y+.5,c,'#83907b14');if(n>.91){const p=project(x+.5,y+.5);ctx.fillStyle='#b9ac7b18';ctx.fillRect(p.x-1,p.y-1,2,2)}}
    // Dust lanes and worn tracks
    for(let x=6;x<17;x++){let y=9+Math.sin(x*.45)*1.4;drawDiamond(x+.5,y+.5,'#97826516')}
    for(let i=0;i<28;i++){const x=terrainSeed(i,8)*COLS,y=terrainSeed(i,19)*ROWS,p=project(x,y);ctx.fillStyle=i%3?'#1a282627':'#d0b98918';ctx.beginPath();ctx.ellipse(p.x,p.y,tw*(.025+terrainSeed(i,4)*.03),th*.08,0,0,Math.PI*2);ctx.fill()}
  }
  function drawHealth(e,p,wide){if(e.hp>=e.maxHp*.995)return;const w=wide||tw*.74,y=p.y-th*.73;ctx.fillStyle='#111918d9';ctx.fillRect(p.x-w/2,y,w,3);ctx.fillStyle=e.team==='blue'?'#5ad2ae':'#ed7660';ctx.fillRect(p.x-w/2,y,w*Math.max(0,e.hp/e.maxHp),3)}

function isoBox(p,w,d,z,top,left,right){const a={x:p.x-w/2,y:p.y-d/2},b={x:p.x+w/2,y:p.y-d/2},c={x:p.x+w/2,y:p.y+d/2},dd={x:p.x-w/2,y:p.y+d/2};const lift=z;ctx.beginPath();ctx.moveTo(a.x,a.y-lift);ctx.lineTo(b.x,b.y-lift);ctx.lineTo(c.x,c.y-lift);ctx.lineTo(dd.x,dd.y-lift);ctx.closePath();ctx.fillStyle=top;ctx.fill();ctx.strokeStyle='#d5d6b52c';ctx.lineWidth=.7;ctx.stroke();ctx.beginPath();ctx.moveTo(dd.x,dd.y-lift);ctx.lineTo(c.x,c.y-lift);ctx.lineTo(c.x,c.y);ctx.lineTo(dd.x,dd.y);ctx.closePath();ctx.fillStyle=left;ctx.fill();ctx.beginPath();ctx.moveTo(b.x,b.y-lift);ctx.lineTo(c.x,c.y-lift);ctx.lineTo(c.x,c.y);ctx.lineTo(b.x,b.y);ctx.closePath();ctx.fillStyle=right;ctx.fill()}
function drawBuilding(b){const p=project(b.x,b.y),blue=b.team==='blue',accent=blue?'#56c9d2':'#df705e';ctx.save();ctx.translate(p.x,p.y);ctx.fillStyle='#11181255';ctx.beginPath();ctx.ellipse(0,th*.18,tw*(b.size*.62),th*(b.size*.27),0,0,Math.PI*2);ctx.fill();ctx.translate(0,-th*.08);
  if(b.type==='hq'){
