  else if(b.type==='barracks'){isoBox({x:0,y:0},tw*.93,th*.68,th*.83,blue?'#74887b':'#86665a',blue?'#485b52':'#604942',blue?'#384842':'#4d3b37');isoBox({x:0,y:-th*.13},tw*.48,th*.44,th*.35,blue?'#87947d':'#967263',blue?'#586359':'#6d5147',blue?'#424d44':'#533f3a');ctx.fillStyle=accent;ctx.fillRect(-tw*.08,-th*.93,tw*.16,th*.12);ctx.fillStyle='#222b28';for(let i=-1;i<=1;i++)ctx.fillRect(i*tw*.2-tw*.035,-th*.43,tw*.07,th*.18)}
  else if(b.type==='refinery'){isoBox({x:0,y:0},tw*1.03,th*.78,th*.68,'#898770','#5c5b4b','#48483e');isoBox({x:-tw*.08,y:-th*.17},tw*.43,th*.36,th*.39,'#9b9873','#696b54','#515341');ctx.fillStyle='#b68754';ctx.fillRect(tw*.2,-th*.68,tw*.12,th*.6);ctx.fillStyle='#3c4841';ctx.fillRect(tw*.22,-th*.76,tw*.08,th*.08);ctx.strokeStyle='#6b7560';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-tw*.38,-th*.2);ctx.lineTo(-tw*.18,-th*.48);ctx.lineTo(-tw*.18,-th*.74);ctx.stroke();ctx.fillStyle=accent;ctx.fillRect(-tw*.15,-th*.82,tw*.13,th*.08)}
  else if(b.type==='generator'){isoBox({x:0,y:0},tw*.78,th*.6,th*.59,'#858976','#555f50','#414b43');ctx.fillStyle=accent;ctx.fillRect(-tw*.05,-th*.67,tw*.1,th*.27);ctx.fillStyle='#d7bd76';ctx.beginPath();ctx.moveTo(tw*.06,-th*.62);ctx.lineTo(-tw*.045,-th*.43);ctx.lineTo(tw*.055,-th*.43);ctx.lineTo(-tw*.04,-th*.24);ctx.lineTo(tw*.14,-th*.49);ctx.lineTo(tw*.045,-th*.49);ctx.fill()}
  else{isoBox({x:0,y:0},tw*.57,th*.5,th*.31,'#798777','#505b4d','#3a4840');ctx.fillStyle=blue?'#a1a78c':'#a98470';ctx.beginPath();ctx.ellipse(0,-th*.57,tw*.2,th*.19,0,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#232b28';ctx.lineWidth=tw*.13;ctx.beginPath();ctx.moveTo(0,-th*.56);ctx.lineTo(tw*.37,-th*.77);ctx.stroke();ctx.fillStyle=accent;ctx.fillRect(-tw*.05,-th*.84,tw*.1,th*.05)}
  if(state.selected.includes(b.id)){ctx.strokeStyle='#b9f1e4';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(0,th*.08,tw*b.size*.68,th*b.size*.3,0,0,Math.PI*2);ctx.stroke()}ctx.restore();drawHealth(b,p,tw*.9)}

