function draw(){ctx.clearRect(0,0,W,H);drawGround();drawDecor();const all=[...state.buildings,...state.units].sort((a,b)=>a.x+a.y-b.x-b.y);for(const e of all){if('size'in e)drawBuilding(e);else drawUnit(e)}drawEffects();if(state.mode==='rally'||state.mode==='turret'||state.mode==='generator'||state.mode==='refinery'){const p=project(state.rally.x,state.rally.y);if(state.mode==='rally'){ctx.fillStyle='#f0bd69';ctx.fillRect(p.x-1,p.y-th*.55,2,th*.48);ctx.fillStyle='#f0bd69';ctx.beginPath();ctx.moveTo(p.x,p.y-th*.52);ctx.lineTo(p.x+tw*.23,p.y-th*.45);ctx.lineTo(p.x,p.y-th*.36);ctx.fill()}}if(pointer?.drag){ctx.strokeStyle='#9de8db';ctx.fillStyle='#6bd9c220';ctx.lineWidth=1;ctx.fillRect(pointer.x,pointer.y,pointer.cx-pointer.x,pointer.cy-pointer.y);ctx.strokeRect(pointer.x,pointer.y,pointer.cx-pointer.x,pointer.cy-pointer.y)}}
const COST={infantry:300,tank:600,turret:450,refinery:500,generator:350};
function updatePower(){const gens=state.buildings.filter(b=>b.team==='blue'&&b.type==='generator').length;const load=100+state.buildings.filter(b=>b.team==='blue'&&b.type==='turret').length*8;state.power=80+gens*60;state.powerMax=load;$('power').textContent=`${state.power} / ${state.powerMax}`;$('power').style.color=state.power<state.powerMax?'#e98b70':''}
function ownerHas(type){return state.buildings.some(b=>b.team==='blue'&&b.type===type)}
function canBuild(action){if(state.gameOver)return false;if(action==='infantry'||action==='tank')return ownerHas('barracks');return true}
function syncButtons(){document.querySelectorAll('.action-card').forEach(b=>b.classList.toggle('disabled',!canBuild(b.dataset.action)||!!COST[b.dataset.action]&&state.credits<COST[b.dataset.action]))}
function startAction(action){if(state.gameOver)return;if(!canBuild(action)){toast('No barracks available');return}if(action==='rally'){state.mode='rally';state.selected=[];ui();toast('Tap a location to set the rally point');return}if(action==='infantry'||action==='tank'){const cost=COST[action];if(state.credits<cost){toast('Insufficient credits');return}const barracks=state.buildings.find(b=>b.team==='blue'&&b.type==='barracks');if(!barracks){toast('Build a barracks first');return}state.credits-=cost;const u=makeUnit('blue',action,barracks.x+1.25,barracks.y+.45);u.move={...state.rally};state.units.push(u);state.selected=[u.id];toast(action==='tank'?'Strike tank deployed':'Rifle squad deployed');ui();return}if(state.credits<COST[action]){toast('Insufficient credits');return}state.mode=action;state.selected=[];ui();toast(`Tap open ground to place ${action}`)}
function nearestEntity(x,y,entities,max){let best=null,bestD=max;for(const e of entities){const d=Math.hypot(e.x-x,(e.y-y)*.72);if(d<bestD){best=e;bestD=d}}return best}
function handleMap(x,y){const pos=unproject(x,y),gx=Math.max(.5,Math.min(COLS-.5,pos.x)),gy=Math.max(.5,Math.min(ROWS-.5,pos.y));
  if(state.mode){if(state.mode==='rally'){state.rally={x:gx,y:gy};state.mode=null;toast('Rally point updated');ui();return}const action=state.mode,cost=COST[action],bx=Math.round(gx),by=Math.round(gy);if(state.credits<cost){toast('Insufficient credits');state.mode=null;ui();return}if(bx<1||bx>COLS-2||by<1||by>ROWS-2){toast('Cannot build at map edge');return}const occupied=state.buildings.some(b=>Math.hypot(b.x-bx,(b.y-by)*.75)<b.size*.75+.55)||state.units.some(u=>Math.hypot(u.x-bx,(u.y-by)*.75)<.45);if(occupied){toast('Location is obstructed');return}if(action==='refinery'&&Math.hypot(bx-11,by-8)>8){toast('Place the refinery closer to the ore basin');return}const building=makeBuilding('blue',action,bx,by);state.buildings.push(building);state.credits-=cost;state.mode=null;state.selected=[building.id];updatePower();toast(`${action.toUpperCase()} construction complete`);ui();return}
  const hit=nearestEntity(gx,gy,[...state.units,...state.buildings],.9);if(hit){if(hit.team==='blue'){if(pointer?.shift)state.selected.push(hit.id);else state.selected=[hit.id];ui();return}const selected=state.selected.map(findEntity).filter(e=>e&&e.team==='blue'&&!('size'in e));if(selected.length){for(const u of selected){u.target=hit.id;u.move=null}toast('Attack target designated');return}}
  const selected=state.selected.map(findEntity).filter(e=>e&&e.team==='blue'&&!('size'in e));if(selected.length){for(const [i,u]of selected.entries()){u.target=null;u.move={x:gx+(i-(selected.length-1)/2)*.3,y:gy}}toast('Move order received');return}state.selected=[];ui()}

